from __future__ import annotations

import os
import threading

from artifact_tool_v2.rpc.client import JsonRpcClient
from artifact_tool_v2.rpc.daemon import start_daemon

_CLIENT: JsonRpcClient | None = None
_LOCK = threading.Lock()


def setup_client(socket_path: str) -> JsonRpcClient:
    """
    Create and cache a client for the given socket path.
    """
    global _CLIENT
    client = JsonRpcClient(socket_path)
    _CLIENT = client
    return client


def get_client() -> JsonRpcClient | None:
    return _CLIENT


def get_or_create_client() -> JsonRpcClient:
    """
    Lazily create a client using env socket or auto-started daemon.
    """
    global _CLIENT
    if _CLIENT is not None:
        return _CLIENT
    with _LOCK:
        if _CLIENT is not None:
            return _CLIENT
        socket_path = os.getenv("ARTIFACT_TOOL_RPC_SOCKET") or start_daemon()
        _CLIENT = JsonRpcClient(socket_path)
        return _CLIENT


